import { normalizeSpeechText, speechKey } from "@/services/speechKey";

test("normalizes to NFC and trims", () => {
  const decomposed = "Xin chào".normalize("NFD");
  expect(decomposed).not.toBe("Xin chào");
  expect(normalizeSpeechText(`  ${decomposed}  `)).toBe("Xin chào");
});

// Shared test vector: generated by scripts/tts/generate_audio.py (sha256 of the UTF-8 NFC text, first 16 hex chars).
test("key matches the Python generator for a known text", async () => {
  expect(await speechKey("Xin chào bạn!")).toBe("761b6118b70fd9d4");
});

test("key is stable across Unicode forms and surrounding spaces", async () => {
  expect(await speechKey(" Xin chào bạn! ".normalize("NFD"))).toBe("761b6118b70fd9d4");
});

test("different texts give different keys", async () => {
  expect(await speechKey("xin chào")).not.toBe(await speechKey("cảm ơn"));
});
